qss:
QWidget { background: #f5f7fb; color: #172033; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #f5f7fb; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #ffffff; border: 1px solid #d0d5dd; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #172033; }
QLabel#SubtleLabel { color: #667085; }
QPushButton { background: #e7ebf2; color: #172033; border: 1px solid #d0d5dd; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #dce2eb; }
QPushButton#AccentButton { background: #2563eb; border: 1px solid #3b82f6; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #3b82f6; }
QPushButton#DangerButton { background: #fee2e2; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #ffffff; color: #172033; border: 1px solid #d0d5dd; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #dbeafe; border: 1px solid #2563eb; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #ffffff; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #d0d5dd; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #d0d5dd; border-radius: 10px; background: #ffffff; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #2563eb; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #ffffff; border: 1px solid #93c5fd; border-left: 4px solid #2563eb; border-radius: 16px; }
QFrame#UserBubbleCard { background: #dbeafe; border: 1px solid #93c5fd; border-radius: 16px; }
